"""Tests for _layout_events column assignment."""

from personal_assistant_dashboard.dashboard import _layout_events


def _ev(
    start_h: int,
    end_h: int,
    eid: str = "",
    summary: str = "x",
    response_status: str = "accepted",
) -> dict:
    """Minimal timed event from hour ints."""
    ev: dict = {
        "start": f"2026-08-12T{start_h:02d}:00:00-04:00",
        "end": f"2026-08-12T{end_h:02d}:00:00-04:00",
        "id": eid or f"{start_h}-{end_h}",
        "summary": summary,
    }
    if response_status:
        ev["attendees"] = [{"self": True, "response_status": response_status}]
    return ev


def _meeting(start_h, end_h, eid, response_status="accepted"):
    """Multi-attendee event (not solo)."""
    ev = _ev(start_h, end_h, eid=eid, response_status=response_status)
    ev["attendees"].append({"email": "other@x.com"})
    return ev


def test_non_overlapping_events_share_column():
    events = [_ev(9, 10), _ev(10, 11), _ev(11, 12)]
    result = _layout_events(events, 8)
    assert all(p["col"] == 0 for p in result)
    assert all(p["num_cols"] == 1 for p in result)


def test_two_overlapping_get_two_columns():
    events = [_ev(9, 11), _ev(10, 12)]
    result = _layout_events(events, 8)
    cols = {p["col"] for p in result}
    assert cols == {0, 1}
    assert all(p["num_cols"] == 2 for p in result)


def test_spanning_event_optimal_columns():
    """Long event + non-overlapping short events = 2 columns, not N."""
    events = [
        _ev(8, 17, eid="long"),
        _ev(9, 10, eid="a"),
        _ev(10, 11, eid="b"),
        _ev(11, 12, eid="c"),
    ]
    result = _layout_events(events, 8)
    assert all(p["num_cols"] == 2 for p in result)


def test_three_way_overlap():
    events = [_ev(9, 12), _ev(10, 13), _ev(11, 14)]
    result = _layout_events(events, 8)
    assert all(p["num_cols"] == 3 for p in result)
    cols = sorted(p["col"] for p in result)
    assert cols == [0, 1, 2]


def test_needs_action_before_accepted():
    """needsAction gets lower column than accepted."""
    events = [
        _meeting(9, 11, "acc", response_status="accepted"),
        _meeting(9, 11, "na", response_status="needsAction"),
    ]
    result = _layout_events(events, 8)
    by_id = {p["event"]["id"]: p for p in result}
    assert by_id["na"]["col"] < by_id["acc"]["col"]


def test_accepted_before_tentative():
    events = [
        _meeting(9, 11, "tent", response_status="tentative"),
        _meeting(9, 11, "acc", response_status="accepted"),
    ]
    result = _layout_events(events, 8)
    by_id = {p["event"]["id"]: p for p in result}
    assert by_id["acc"]["col"] < by_id["tent"]["col"]


def test_dismissed_goes_rightmost():
    events = [
        _meeting(9, 11, "acc", response_status="accepted"),
        _meeting(9, 11, "dismissed_acc", response_status="accepted"),
    ]
    result = _layout_events(events, 8, dismissed_conflicts={"dismissed_acc"})
    by_id = {p["event"]["id"]: p for p in result}
    assert by_id["acc"]["col"] < by_id["dismissed_acc"]["col"]


def test_accepted_left_of_tentative_spanning():
    """Accepted gets lower col than tentative, even if tentative spans all day."""
    events = [
        _meeting(8, 17, "allday", response_status="tentative"),
        _meeting(9, 10, "morning", response_status="accepted"),
        _meeting(14, 15, "afternoon", response_status="accepted"),
    ]
    result = _layout_events(events, 8)
    by_id = {p["event"]["id"]: p for p in result}
    assert all(p["num_cols"] == 2 for p in result)
    # accepted events share col 0, tentative all-day goes to col 1
    assert by_id["morning"]["col"] == 0
    assert by_id["afternoon"]["col"] == 0
    assert by_id["allday"]["col"] == 1


def test_realistic_day():
    """Simulates: all-day tentative + scattered accepted + 3-way overlap spot."""
    events = [
        _meeting(8, 17, "auto", response_status="tentative"),
        _meeting(8, 9, "aap", response_status="accepted"),
        _meeting(8, 10, "gsd", response_status="needsAction"),
        _meeting(10, 11, "ao1", response_status="accepted"),
        _meeting(13, 15, "gsd2", response_status="accepted"),
        _meeting(15, 16, "ao2", response_status="accepted"),
    ]
    result = _layout_events(events, 7)
    by_id = {p["event"]["id"]: p for p in result}
    # 3-way overlap at 8-9: auto + aap + gsd → 3 columns
    assert all(p["num_cols"] == 3 for p in result)
    # needsAction left of tentative

    assert by_id["gsd"]["col"] < by_id["auto"]["col"]


def test_empty_events():
    assert _layout_events([], 8) == []
